package com.mahesh.empleave.leavebalance;import com.mahesh.empleave.leavetype.*;import com.mahesh.empleave.user.*;import jakarta.persistence.*;import lombok.*;import java.math.*;@Entity @Table(uniqueConstraints=@UniqueConstraint(columnNames={"user_id","leaveType_id"})) @Getter @NoArgsConstructor(access=AccessLevel.PROTECTED) public class LeaveBalance{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@ManyToOne(optional=false) private AppUser user;@ManyToOne(optional=false) private LeaveType leaveType;@Column(nullable=false,precision=7,scale=2) private BigDecimal remainingDays;@Version private Long version;public LeaveBalance(AppUser u,LeaveType t,BigDecimal d){user=u;leaveType=t;remainingDays=d;}public void debit(int days){if(remainingDays.compareTo(BigDecimal.valueOf(days))<0)throw new IllegalStateException("Insufficient leave balance");remainingDays=remainingDays.subtract(BigDecimal.valueOf(days));}public void credit(int days){remainingDays=remainingDays.add(BigDecimal.valueOf(days));}public void adjust(BigDecimal delta){if(remainingDays.add(delta).signum()<0)throw new IllegalArgumentException("Adjustment would make balance negative");remainingDays=remainingDays.add(delta);}}
